let state;
try { const stored=JSON.parse(localStorage.getItem(STORAGE_KEY)); state=stored?.schema===2?stored:seed(); } catch { state=seed(); }
let searchQuery='', campaignFilter='all', leadFilter='all', leadCampaign='all', contentFilter='all';
const main=document.getElementById('main'), dialog=document.getElementById('dialog');
const navigation=[{label:'OPERACIÓN',items:[['overview','Centro de mando','grid'],['contactability','Contactabilidad','target'],['campaigns','Campañas','campaign'],['content','Estudio de contenido','content'],['inbox','Conversaciones','message'],['crm','Prospectos y ventas','users']]},{label:'INTELIGENCIA',items:[['results','Resultados','chart'],['lab','Pruebas y aprendizaje','lab']]},{label:'ADMINISTRACIÓN',items:[['profile','Perfil de marca','settings'],['connections','Conexiones y datos','plug'],['team','Equipo y control','shield']],admin:true}];
const titles={overview:['Operación','Centro de mando'],contactability:['Operación','Contactabilidad'],campaigns:['Operación','Campañas'],content:['Operación','Estudio de contenido'],inbox:['Operación','Conversaciones'],crm:['Operación','Prospectos y ventas'],results:['Inteligencia','Resultados'],lab:['Inteligencia','Pruebas y aprendizaje'],profile:['Administración','Perfil de marca'],connections:['Administración','Conexiones y datos'],team:['Administración','Equipo y control'],guide:['Inteligencia','Guía de medición']};
const adminViews=['profile','connections','team'];
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('El navegador no permite guardar. Los cambios quedan solo en esta sesión.');}}
function log(text){state.audit.unshift({time:new Date().toLocaleString('es-MX',{timeZone:'America/Mexico_City'}),text});state.audit=state.audit.slice(0,30);save();}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4000);}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=ico(el.dataset.icon));}
function filteredLeads(channel=state.channel){return state.leads.filter(l=>(channel==='all'||l.source===channel)&&(state.period==='30'||l.date>='2026-10-07'));}
function activeCampaigns(channel=state.channel){return state.campaigns.filter(c=>channel==='all'||c.channel===channel);}
function aggregate(channel=state.channel){const leads=filteredLeads(channel),won=leads.filter(l=>l.stage==='Ganado'),lost=leads.filter(l=>l.stage==='Perdido'),contacted=leads.filter(l=>l.contacted),qualified=leads.filter(l=>l.qualified);const spend=activeCampaigns(channel).reduce((sum,c)=>sum+(state.period==='7'?(c.id==='camp-web'?2800:c.id==='camp-social'?3900:0):c.spend),0);const attributed=won.reduce((sum,l)=>sum+l.attributedValue,0),revenue=won.reduce((sum,l)=>sum+l.value,0);const response=leads.map(l=>l.responseMinutes).filter(x=>typeof x==='number').sort((a,b)=>a-b);const median=response.length?(response[Math.floor((response.length-1)/2)]+response[Math.ceil((response.length-1)/2)])/2:null;const p90=response.length?response[Math.max(0,Math.ceil(response.length*.9)-1)]:null;return{leads,won,lost,contacted,qualified,qualifiedAttributed:qualified.filter(l=>l.campaign),spend,attributed,revenue,median,p90,pending:leads.filter(l=>!l.contacted),slaResponded:response.filter(x=>x<=state.profile.sla).length,responseCount:response.length};}
function filters(includeChannel=true){return `${includeChannel?`<label class="sr-only" for="channel-filter">Canal</label><select id="channel-filter" class="period-select"><option value="all" ${state.channel==='all'?'selected':''}>Todos los canales</option><option value="meta" ${state.channel==='meta'?'selected':''}>Meta</option><option value="google" ${state.channel==='google'?'selected':''}>Google</option><option value="direct" ${state.channel==='direct'?'selected':''}>Directo / referido</option></select>`:''}<label class="sr-only" for="period-filter">Periodo</label><select id="period-filter" class="period-select"><option value="30" ${state.period==='30'?'selected':''}>Últimos 30 días</option><option value="7" ${state.period==='7'?'selected':''}>Últimos 7 días</option></select>`;}
function heading(title,subtitle,actions='',eyebrow='VECTOR / OPERACIÓN CONECTADA'){return `<div class="page-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function button(label,icon,action,cls=''){return `<button class="button ${cls}" ${action}>${ico(icon)}${esc(label)}</button>`;}
function kpi(label,value,foot,metric,source='CRM demo'){return `<article class="kpi"><div class="kpi-top"><span>${esc(label)}</span><button class="metric-info" data-metric="${metric}" aria-label="Definición de ${esc(label)}">${ico('info')}</button></div><div class="kpi-value">${esc(value)}</div><div class="kpi-foot">${esc(foot)} <span class="source-label">${esc(source)}</span></div></article>`;}
function syncSidebar(){const sidebar=document.getElementById('sidebar'),hidden=window.innerWidth<=760&&!sidebar.classList.contains('open');sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden));}
function renderNav(){syncSidebar();const pending=state.leads.filter(l=>!l.contacted).length;document.getElementById('navigation').innerHTML=navigation.filter(g=>!g.admin||state.role==='admin').map(g=>`<p class="nav-label">${g.label}</p>${g.items.map(([view,title,icon])=>`<button class="nav-item ${state.view===view?'active':''}" data-view="${view}" ${state.view===view?'aria-current="page"':''}><span class="icon">${ico(icon)}</span>${title}${view==='inbox'?`<span class="count">${pending}</span>`:view==='content'?`<span class="count">${state.posts.filter(p=>p.status==='Revisión').length}</span>`:''}</button>`).join('')}`).join('');document.getElementById('pending-dot').hidden=pending===0;document.getElementById('role-select').value=state.role;document.getElementById('avatar').textContent=state.role==='admin'?'KV':'VI';document.body.classList.toggle('light',state.theme==='light');document.getElementById('theme-button').innerHTML=ico(state.theme==='light'?'moon':'sun');}
function navigate(view){if(!titles[view])view='overview';if(state.role!=='admin'&&adminViews.includes(view)){toast('La configuración corresponde al Administrador en este prototipo.');return;}state.view=view;searchQuery='';save();render();document.getElementById('sidebar').classList.remove('open');document.getElementById('menu-button').setAttribute('aria-expanded','false');syncSidebar();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function render(){if(state.role!=='admin'&&adminViews.includes(state.view))state.view='overview';renderNav();document.getElementById('breadcrumb').textContent=titles[state.view].join(' / ');const views={overview,contactability,campaigns,content,inbox,crm,results,lab,profile,connections,team,guide};main.innerHTML=views[state.view]();hydrateIcons();}
function openDialog(title,body,eyebrow='VECTOR / DETALLE CON CONTEXTO'){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-eyebrow').textContent=eyebrow;document.getElementById('dialog-body').innerHTML=body;hydrateIcons(dialog);if(!dialog.open)dialog.showModal();}
function closeDialog(){dialog.close();}

function chart(){const leads=filteredLeads();const count=state.period==='7'?7:13;const start=state.period==='7'?7:1;const values=Array.from({length:count},(_,i)=>leads.filter(l=>Number(l.date.slice(-2))===i+start).length);const answered=Array.from({length:count},(_,i)=>leads.filter(l=>l.contacted&&Number(l.date.slice(-2))===i+start).length);const max=Math.max(3,...values);const viewport=window.innerWidth,sidebarWidth=viewport>1000?248:viewport>760?210:0,padding=viewport>=1500?84:viewport>1000?62:viewport>760?40:32,contentWidth=Math.min(viewport-sidebarWidth,1600)-padding;const w=Math.max(250,viewport>1000?(contentWidth-20)*(viewport>1200?1.6/2.6:1.4/2.4)-44:contentWidth-38),h=210,left=30,right=w-15,top=20,bottom=170;const points=arr=>arr.map((v,i)=>`${left+i/(count-1)*(right-left)},${bottom-v/max*(bottom-top)}`).join(' ');const area=`${left},${bottom} ${points(values)} ${right},${bottom}`;return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Contactos nuevos y contactos atendidos por fecha de captura. Datos ficticios."><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c3f400" stop-opacity=".13"/><stop offset="1" stop-color="#c3f400" stop-opacity="0"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const y=top+i/3*(bottom-top);return `<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="var(--border)" stroke-dasharray="3 5"/><text x="9" y="${y+4}">${Math.round(max-i/3*max)}</text>`;}).join('')}<polygon points="${area}" fill="url(#chart-fill)"/><polyline points="${points(values)}" fill="none" stroke="#c3f400" stroke-width="2.5"/><polyline points="${points(answered)}" fill="none" stroke="var(--purple)" stroke-width="2"/>${[0,Math.floor((count-1)/3),Math.floor((count-1)*2/3),count-1].map(i=>`<text x="${left+i/(count-1)*(right-left)}" y="196" text-anchor="${i===0?'start':i===count-1?'end':'middle'}">${i+start} oct</text>`).join('')}${values.map((v,i)=>`<circle cx="${left+i/(count-1)*(right-left)}" cy="${bottom-v/max*(bottom-top)}" r="3" fill="#c3f400"><title>${i+start} oct: ${v} contactos, ${answered[i]} atendidos</title></circle>`).join('')}</svg>`;}
function funnel(){const m=aggregate();const rows=[['Captaciones válidas',m.leads.length],['Contacto bidireccional',m.contacted.length],['Calificados',m.qualified.length],['Ventas ganadas',m.won.length]];return rows.map(([label,value],i)=>`<div class="funnel-row"><span class="label">${label}</span><span class="value">${value}</span><div class="funnel-track"><div class="funnel-fill" style="width:${m.leads.length?value/m.leads.length*100:0}%;opacity:${1-i*.16}"></div></div></div>`).join('');}
function overview(){const m=aggregate();const unassigned=m.leads.filter(l=>l.owner==='Sin asignar').length;const missingNext=m.leads.filter(l=>!l.next&&!['Ganado','Perdido'].includes(l.stage)).length;const review=state.posts.filter(p=>p.status==='Revisión').length;return `${heading('Tu marketing, conectado.','De la presencia a la conversación. De la conversación al siguiente paso.',filters())}<section class="hero-panel"><div><p class="eyebrow">DIRECCIÓN CLARA / ACCIÓN CONCRETA</p><h2>El interés ya llegó.<br>Ahora, dale continuidad.</h2><p>${m.pending.length} consultas esperan atención. ${unassigned} todavía no tienen responsable. Este es el siguiente punto que puedes mejorar.</p><button class="hero-button" data-view="inbox">Atender conversaciones ${ico('arrow')}</button></div><img class="hero-wolf" src="assets/vector-wolf.png" alt="" aria-hidden="true"></section><div class="kpi-grid">${kpi('Contactos nuevos',m.leads.length,'Personas únicas de la cohorte','leads')}${kpi('Contactabilidad',pct(m.contacted.length,m.leads.length),`${m.contacted.length} de ${m.leads.length} con intercambio confirmado`,'contactability')}${kpi('Prospectos calificados',m.qualified.length,'Necesidad y ajuste evaluados','qualified')}${kpi('Ventas ganadas',money(m.revenue),'Importe comercial · no cobros','revenue')}</div><div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-head"><div><h2>De la consulta a la atención</h2><p>Contactos por fecha de captura · ${state.period==='7'?'7–13':'1–13'} de octubre</p></div>${button('Ver detalle','arrow','data-view="contactability"')}</div><div class="chart-legend"><span><i class="legend-dot"></i>Contactos nuevos</span><span><i class="legend-dot secondary"></i>Con intercambio confirmado</span></div>${chart()}<div class="chart-summary"><span>Primera respuesta humana<strong>${m.median!==null?m.median+' min':'Sin datos'}</strong></span><span>Percentil 90<strong>${m.p90!==null?m.p90+' min':'Sin datos'}</strong></span><span>Objetivo interno<strong>${state.profile.sla} min</strong></span></div><p class="footnote">Objetivo editable, no benchmark. Respuestas de demo medidas dentro del horario definido.</p></section><section class="panel panel-pad"><div class="panel-head"><div><h2>El recorrido comercial</h2><p>Misma cohorte · IDs únicos del CRM</p></div>${button('Abrir CRM','arrow','data-view="crm"')}</div>${funnel()}<div class="insight"><h3>${ico('sparkle')} El siguiente paso tiene impacto</h3><p>${missingNext} oportunidades abiertas no tienen próxima acción. Empieza por las consultas que ya expresan una necesidad.</p>${button('Organizar seguimiento','arrow','data-view="crm"','link')}</div></section></div><div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-head"><h2>Necesita tu atención</h2><span class="task-chip">${m.pending.length+review} pendientes</span></div><div class="attention-list"><div class="attention-row"><div class="attention-icon orange">${ico('message')}</div><div class="copy"><strong>${m.pending.length} consultas esperan atención</strong><p>Asigna responsable y prepara una respuesta útil.</p></div>${button('Atender','arrow','data-view="inbox"')}</div><div class="attention-row"><div class="attention-icon">${ico('content')}</div><div class="copy"><strong>${review} versiones requieren revisión</strong><p>Aprueba la pieza exacta o solicita cambios.</p></div>${button('Revisar','arrow','data-view="content"')}</div>${state.tasks.filter(t=>!t.done).slice(0,3).map(t=>`<div class="attention-row"><div class="attention-icon">${ico('clock')}</div><div class="copy"><strong>${esc(t.title)}</strong><p>${esc(t.owner)} · ${esc(t.type)}</p></div>${button('Completar','check',`data-complete-task="${t.id}"`)}</div>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-head"><h2>Una lectura con evidencia</h2>${ico('shield')}</div><div class="metric-row"><span>Origen identificado<small>${m.leads.filter(l=>l.campaign).length} registros vinculados a campaña</small></span><b>${pct(m.leads.filter(l=>l.campaign).length,m.leads.length)}</b></div><div class="metric-row"><span>Inversión de demostración<small>Fuentes de campaña · MXN</small></span><b>${money(m.spend)}</b></div><div class="metric-row"><span>ROAS comercial<small>Venta atribuida / gasto publicitario</small></span><b>${m.spend?(m.attributed/m.spend).toFixed(2)+'x':'N/C'}</b></div><p class="footnote">Las atribuciones del CRM y las reportadas por plataformas se consultan por separado. Cada cifra de este prototipo es ficticia.</p>${button('Explorar resultados','arrow','data-view="results"','link')}</section></div><div class="section-heading"><h2>Tus puntos de contacto</h2>${button('Ver fuentes y conexiones','arrow','data-view="guide"','link')}</div><div class="source-grid"><article class="source-card"><div class="source-top"><span class="platform-icon meta">∞</span><h3>Meta Business</h3>${badge('Demo','purple')}</div><div class="source-stats"><span>Contactos CRM<b>${m.leads.filter(l=>l.source==='meta').length}</b></span><span>Atendidos<b>${m.contacted.filter(l=>l.source==='meta').length}</b></span><span>Calificados<b>${m.qualified.filter(l=>l.source==='meta').length}</b></span></div><p>Contenido, publicidad y atención en contexto.</p></article><article class="source-card"><div class="source-top"><span class="platform-icon google">G</span><h3>Google</h3>${badge('Demo','purple')}</div><div class="source-stats"><span>Contactos CRM<b>${m.leads.filter(l=>l.source==='google').length}</b></span><span>Atendidos<b>${m.contacted.filter(l=>l.source==='google').length}</b></span><span>Calificados<b>${m.qualified.filter(l=>l.source==='google').length}</b></span></div><p>Búsqueda, perfil local y experiencia web.</p></article><article class="source-card"><div class="source-top"><span class="platform-icon instagram">↗</span><h3>Aprendizaje activo</h3>${badge('Por validar','orange')}</div><div class="source-stats"><span>Pruebas propuestas<b>${state.experiments.length}</b></span><span>Ganadores validados<b>0</b></span></div><p>Probar una hipótesis y registrar qué cambió.</p>${button('Abrir laboratorio','arrow','data-view="lab"','link')}</article></div>`;}

function contactability(){const m=aggregate();const factor=state.period==='7'?.28:1;const webSessions=Math.round((state.channel==='meta'?1280:state.channel==='google'?1140:state.channel==='direct'?190:2610)*factor);const intent=Math.round(webSessions*.085);return `${heading('Convierte atención en contacto.','Descubre dónde se interrumpe el recorrido y qué puede hacer el equipo para mejorarlo.',filters(),'VECTOR / ARQUITECTURA DE CONTACTO')}<div class="research-banner"><h3>Encontrarte, conversar y recibir seguimiento son pasos distintos.</h3><p>Meta ayuda a generar y atender conversaciones. Search Console muestra cómo te descubren; Business Profile, cómo interactúan con tu perfil; GA4, qué ocurre en tu web.</p></div><div class="flow-grid"><section class="panel panel-pad"><div class="panel-head"><div><h2>Atención que avanza</h2><p>Cohorte CRM · ${m.leads.length} captaciones únicas</p></div>${button('Definición','info','data-metric="contactability"')}</div><div class="contactability-hero"><div><div class="big-number">${pct(m.contacted.length,m.leads.length)}</div><p>Contactabilidad: intercambio bidireccional confirmado, no solo un mensaje enviado.</p></div><div class="ratio-ring" style="--progress:${m.leads.length?m.contacted.length/m.leads.length*360:0}deg"><span>${m.contacted.length}/${m.leads.length}</span></div></div>${funnel()}<div class="insight"><h3>${ico('target')} Acción antes que más alcance</h3><p>${m.pending.length} consultas todavía no tienen intercambio confirmado. Elige una, revisa su necesidad y registra el siguiente paso.</p>${button('Abrir bandeja priorizada','arrow','data-view="inbox"','primary')}</div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>Capacidad de atención</h2><p>${esc(state.profile.hours)}</p></div>${state.role==='admin'?button('Configurar','settings','data-view="profile"'):''}</div><div class="metric-row"><span>Primera respuesta humana<small>Mediana de los casos con respuesta</small></span><b>${m.median!==null?m.median+' min':'Sin datos'}</b></div><div class="metric-row"><span>Respuesta lenta (p90)<small>90% de las respuestas están por debajo de este tiempo</small></span><b>${m.p90!==null?m.p90+' min':'Sin datos'}</b></div><div class="metric-row"><span>Dentro del objetivo interno<small>${m.slaResponded} de ${m.leads.length} consultas elegibles · pendientes incluidos</small></span><b>${pct(m.slaResponded,m.leads.length)}</b></div><div class="metric-row"><span>Consultas sin responsable<small>Riesgo operativo verificable</small></span><b>${m.leads.filter(l=>l.owner==='Sin asignar').length}</b></div><p class="footnote">Objetivo de ${state.profile.sla} min propuesto para esta demo; no es una promesa de Meta o Google. El acuse automático no se cuenta como respuesta humana.</p>${button('Crear tarea de cobertura','plus','data-create-task="Revisar cobertura de atención y responsable de respaldo"','purple')}</section></div><div class="section-heading"><h2>Antes del contacto: experiencia web</h2><p>Valores de ejemplo independientes del CRM</p></div><div class="kpi-grid">${kpi('Sesiones web',num(webSessions),'Tráfico elegible de ejemplo','sessions','GA4 demo')}${kpi('Intenciones de contacto',num(intent),'Clics al canal · no conversaciones','intent','GA4 demo')}${kpi('Sesiones con lead válido',m.leads.length,'Un lead confirmado por sesión en el fixture','webconversion','GA4 demo')}${kpi('Conversión web a lead',pct(m.leads.length,webSessions),'Sesiones con lead / sesiones elegibles','webconversion','GA4 demo')}</div><section class="panel panel-pad"><div class="panel-head"><div><h2>Un plan para mejorar el recorrido</h2><p>Recomendaciones derivadas de la investigación; validar con datos reales.</p></div>${button('Ver fuentes oficiales','book','data-view="guide"')}</div><div class="compact-grid">${[['Oferta y llamada a la acción','Que el perfil y la landing expliquen qué resuelves, para quién y cómo empezar.','Revisar oferta, CTA y enlace de contacto'],['Menos fricción, mejor contexto','Pedir lo necesario para orientar la respuesta; explicar quién atenderá y cuándo.','Probar formulario breve y confirmación'],['Conversaciones con dueño','Asignar, registrar preferencias y acordar el siguiente paso.','Asignar responsable a consultas pendientes'],['Google coherente con la marca','Datos y horarios correctos, páginas por servicio y atención de reseñas.','Revisar presencia y servicios en Google']].map(([title,text,task])=>`<div class="insight"><h3>${title}</h3><p>${text}</p>${button('Convertir en tarea','plus',`data-create-task="${task}"`,'link')}</div>`).join('')}</div></section>`;}

function campaigns(){const list=state.campaigns.filter(c=>(campaignFilter==='all'||c.channel===campaignFilter)&&(!searchQuery||`${c.name} ${c.offer}`.toLowerCase().includes(searchQuery.toLowerCase())));return `${heading('Una campaña. Todo el recorrido.','Oferta, contenido, inversión y oportunidades conectados con un objetivo.',state.role==='admin'?button('Nueva campaña','plus','data-new-campaign','primary'):button('Proponer una campaña','plus','data-propose-campaign','primary'),'VECTOR / DIRECCIÓN ESTRATÉGICA')}<div class="toolbar"><label class="input-search">${ico('search')}<input id="campaign-search" placeholder="Buscar campaña u oferta" value="${esc(searchQuery)}" aria-label="Buscar campañas"></label><div class="button-row"><label class="sr-only" for="campaign-filter">Filtrar canal</label><select class="select" id="campaign-filter"><option value="all">Todos los canales</option><option value="meta" ${campaignFilter==='meta'?'selected':''}>Meta</option><option value="google" ${campaignFilter==='google'?'selected':''}>Google</option></select>${button('Crear enlace UTM','link','data-utm')}</div></div><div class="campaign-grid">${list.map(c=>{const lead=state.leads.filter(l=>l.campaign===c.id),q=lead.filter(l=>l.qualified),posts=state.posts.filter(p=>p.campaign===c.id);return `<article class="campaign-card"><div class="campaign-banner ${esc(c.color)}">${c.channel==='meta'?'Contenido que conversa.':'Una web que convierte.'}</div><div class="campaign-card-body">${badge(c.status,c.status==='Activa'?'green':'orange')}<h3>${esc(c.name)}</h3><p>${esc(c.offer)}</p><div class="campaign-meta"><span>${sourceName(c.channel)}</span><span>Responsable: ${esc(c.owner)}</span></div><div class="source-stats"><span>Contactos<b>${lead.length}</b></span><span>Calificados<b>${q.length}</b></span><span>Piezas<b>${posts.length}</b></span></div><div class="separator"></div><div class="kpi-foot">Inversión / presupuesto <strong style="margin-left:auto;color:var(--text)">${money(c.spend)} / ${money(c.budget)}</strong></div><div class="campaign-progress"><span style="width:${c.budget?Math.min(c.spend/c.budget*100,100):0}%"></span></div><p class="footnote">${shortDate(c.start)}–${shortDate(c.end)} · Datos demo</p></div><div class="campaign-bottom"><span>${esc(c.objective)}</span><button data-campaign="${c.id}">Explorar ${ico('arrow')}</button></div></article>`;}).join('')}</div>${list.length?'':'<div class="empty-state"><h3>No hay campañas con ese filtro.</h3><p>Prueba otro término o canal.</p></div>'}<div class="research-banner" style="margin-top:25px"><h3>La campaña comienza con una hipótesis.</h3><p>Comparar mensajes, rutas y públicos por calidad de consulta ayuda a decidir. Más clics no bastan para declarar éxito.</p>${button('Preparar una prueba','lab','data-view="lab"','link')}</div>`;}
function campaignDetail(id){const c=state.campaigns.find(c=>c.id===id);if(!c)return;const leads=state.leads.filter(l=>l.campaign===id),posts=state.posts.filter(p=>p.campaign===id);openDialog(c.name,`<p>${esc(c.offer)}</p><div class="detail-grid"><div class="detail-item">Objetivo<strong>${esc(c.objective)}</strong></div><div class="detail-item">Responsable<strong>${esc(c.owner)}</strong></div><div class="detail-item">Público<strong>${esc(c.audience)}</strong></div><div class="detail-item">Periodo<strong>${shortDate(c.start)}–${shortDate(c.end)}</strong></div></div><div class="metric-definition"><small>HIPÓTESIS DE TRABAJO</small><p>${esc(c.hypothesis)}</p></div><div class="source-stats"><span>Contactos<b>${leads.length}</b></span><span>Calificados<b>${leads.filter(l=>l.qualified).length}</b></span><span>Inversión<b>${money(c.spend)}</b></span></div><div class="separator"></div><h3>Contenido de la campaña</h3><div class="search-results">${posts.map(p=>`<button class="search-result" data-post="${p.id}"><span>${esc(p.title)} <small>· v${p.version}</small></span>${badge(p.status)}</button>`).join('')||'<p class="footnote">Sin piezas todavía. Crea una desde el estudio.</p>'}</div><div class="form-actions">${button('Ver oportunidades','users',`data-campaign-leads="${id}"`)}${button('Crear enlace de campaña','link',`data-utm="${id}"`,'primary')}</div>`,'VECTOR / CAMPAÑA CONECTADA');}
function campaignForm(proposal=false){openDialog(proposal?'Proponer una campaña':'Preparar una nueva campaña',`<p>Empieza por el problema, la oferta y una acción concreta. ${proposal?'La propuesta quedará para revisión del Administrador.':'Se guarda en esta demostración local.'}</p><form id="campaign-form"><div class="form-grid"><div class="field wide"><label for="camp-name">Nombre de la campaña</label><input id="camp-name" name="name" required maxlength="90" placeholder="Ej. Una consulta con siguiente paso"></div><div class="field wide"><label for="camp-offer">Oferta / problema que resolvemos</label><textarea id="camp-offer" name="offer" required maxlength="400"></textarea></div><div class="field"><label for="camp-channel">Canal principal</label><select id="camp-channel" name="channel"><option value="meta">Meta</option><option value="google">Google</option></select></div><div class="field"><label for="camp-objective">Objetivo</label><select id="camp-objective" name="objective"><option>Conversaciones calificadas</option><option>Captación de leads</option><option>Demanda orgánica</option></select></div><div class="field"><label for="camp-audience">Público</label><input id="camp-audience" name="audience" required maxlength="180"></div><div class="field"><label for="camp-budget">Presupuesto previsto (MXN)</label><input type="number" min="0" max="10000000" step="1" id="camp-budget" name="budget" value="0" required></div><div class="field wide"><label for="camp-hypothesis">¿Qué queremos aprender?</label><input id="camp-hypothesis" name="hypothesis" required maxlength="300"></div></div><div class="form-actions">${button('Cancelar','close','type="button" data-close-dialog')}${button(proposal?'Guardar propuesta':'Crear campaña','check','type="submit"','primary')}</div></form>`);document.getElementById('campaign-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);const c={id:`camp-${Date.now()}`,name:fd.get('name').trim(),offer:fd.get('offer').trim(),channel:fd.get('channel'),objective:fd.get('objective'),audience:fd.get('audience').trim(),budget:Number(fd.get('budget')),spend:0,hypothesis:fd.get('hypothesis').trim(),color:'purple',status:proposal?'Propuesta':'En preparación',owner:state.role==='admin'?'Karloz':'Usuario de marca',start:DEMO_DATE,end:'2026-10-31'};state.campaigns.push(c);log(`Campaña ${proposal?'propuesta':'creada'}: ${c.name}`);closeDialog();render();toast('Campaña guardada en la demo local.');});}

function content(){const posts=state.posts.filter(p=>(contentFilter==='all'||p.status===contentFilter)&&(!searchQuery||`${p.title} ${p.copy}`.toLowerCase().includes(searchQuery.toLowerCase())));return `${heading('Contenido con dirección.','Cada pieza tiene una intención, una campaña y una versión que puedes revisar.',button('Nueva pieza','plus','data-new-post','primary'),'VECTOR / ESTUDIO DE CONTENIDO')}<div class="toolbar"><div class="button-row"><div class="tabs" style="margin:0;border:0"><button class="${state.contentMode==='cards'?'active':''}" data-content-mode="cards">Piezas</button><button class="${state.contentMode==='calendar'?'active':''}" data-content-mode="calendar">Calendario</button></div></div><div class="button-row"><label class="sr-only" for="content-filter">Estado de contenido</label><select class="select" id="content-filter"><option value="all">Todos los estados</option>${['Borrador','Revisión','Aprobado','Publicado'].map(s=>`<option ${contentFilter===s?'selected':''}>${s}</option>`).join('')}</select>${button('Preparar ideas','sparkle','data-ideas','purple')}</div></div><div class="metric-note">Aprobación por versión · Publicación manual en este prototipo · Ninguna pieza se envía a Meta</div>${state.contentMode==='calendar'?calendar(posts):`<div class="content-layout">${posts.map(p=>`<article class="content-card"><div class="post-preview ${esc(p.color)}"><span>${esc(p.platform)} / ${esc(p.format)}</span><strong>${esc(p.hook)}</strong><small>VECTOR INSIDE / ${esc(p.pillar).toUpperCase()}</small></div><div class="content-body">${badge(p.status)}<h3>${esc(p.title)}</h3><p>${esc(state.campaigns.find(c=>c.id===p.campaign)?.name||'Sin campaña')} · ${esc(p.owner)}</p><div class="content-actions"><span class="muted" style="font-size:10px">${shortDate(p.date)} · v${p.version}</span>${button(p.status==='Revisión'?'Revisar versión':'Abrir pieza','eye',`data-post="${p.id}"`)}</div></div></article>`).join('')}</div>`}${posts.length?'':'<div class="empty-state"><h3>No hay piezas con ese estado.</h3><p>Prueba otro filtro o prepara una nueva pieza.</p></div>'}`;}
function calendar(posts){return `<div class="table-wrap"><div class="calendar-week">${Array.from({length:7},(_,i)=>{const date=`2026-10-${13+i}`,day=new Intl.DateTimeFormat('es-MX',{weekday:'short',timeZone:'America/Mexico_City'}).format(new Date(`${date}T12:00:00-06:00`));return `<section class="calendar-day"><p>${day.toUpperCase()}</p><b>${13+i}</b>${posts.filter(p=>p.date===date).map(p=>`<button class="calendar-post" data-post="${p.id}">${esc(p.platform)}<strong>${esc(p.title)}</strong><small>${esc(p.status)} · v${p.version}</small></button>`).join('')}</section>`;}).join('')}</div></div><p class="footnote">Semana de ejemplo: 13–19 de octubre de 2026. La fecha prevista no implica programación en una plataforma.</p>`;}
function postDetail(id){const p=state.posts.find(p=>p.id===id);if(!p)return;openDialog(p.title,`<div class="button-row" style="margin-bottom:17px">${badge(p.status)}<span class="source-label">Versión ${p.version}</span><span class="source-label">${esc(p.platform)} · ${esc(p.format)}</span></div><div class="dialog-preview"><strong>${esc(p.hook)}</strong><p>${esc(p.copy)}</p></div><div class="detail-grid"><div class="detail-item">Campaña<strong>${esc(state.campaigns.find(c=>c.id===p.campaign)?.name||'Sin campaña')}</strong></div><div class="detail-item">Publicación manual prevista<strong>${shortDate(p.date)}</strong></div><div class="detail-item">Responsable<strong>${esc(p.owner)}</strong></div><div class="detail-item">Llamada a la acción<strong>${esc(p.cta)}</strong></div></div>${p.approval?`<div class="metric-note">Versión ${p.approval.version} aprobada por ${esc(p.approval.by)} · ${esc(p.approval.date)}. Una edición exige nueva revisión.</div>`:''}${p.feedback?`<div class="metric-note">Cambios solicitados: ${esc(p.feedback)}</div>`:''}<p class="footnote">Aprobar registra una decisión local. No publica ni programa contenido real.</p><div class="form-actions">${state.role==='admin'?button('Editar / nueva versión','edit',`data-edit-post="${id}"`):''}${p.status==='Revisión'?`${button('Solicitar cambios','message',`data-changes-post="${id}"`)}${button('Aprobar esta versión','check',`data-approve-post="${id}"`,'primary')}`:p.status==='Borrador'&&state.role==='admin'?button('Solicitar revisión','arrow',`data-review-post="${id}"`,'primary'):p.status==='Aprobado'&&state.role==='admin'?button('Registrar publicación manual','link',`data-publish-post="${id}"`,'primary'):''}</div>`,'VECTOR / REVISIÓN EDITORIAL');}
function postForm(id){if(state.role!=='admin'&&id){toast('El Administrador prepara las versiones. Puedes solicitar cambios.');return;}const p=id?state.posts.find(x=>x.id===id):null;openDialog(p?'Crear una nueva versión':'Preparar una pieza',`<p>${p?'Editar invalida la aprobación anterior y conserva su evidencia en el historial de la demo.':'Conecta una sola idea con la oferta y el objetivo de campaña.'}</p><form id="post-form"><div class="form-grid"><div class="field wide"><label for="post-title">Nombre de la pieza</label><input id="post-title" name="title" required maxlength="100" value="${esc(p?.title||'')}"></div><div class="field wide"><label for="post-hook">Gancho / mensaje principal</label><input id="post-hook" name="hook" required maxlength="160" value="${esc(p?.hook||'')}"></div><div class="field wide"><label for="post-copy">Texto de la publicación</label><textarea id="post-copy" name="copy" required maxlength="3000">${esc(p?.copy||'')}</textarea></div><div class="field"><label for="post-campaign">Campaña</label><select id="post-campaign" name="campaign">${state.campaigns.map(c=>`<option value="${c.id}" ${p?.campaign===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="post-format">Formato</label><select id="post-format" name="format">${['Reel','Carrusel','Post','Story'].map(f=>`<option ${p?.format===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label for="post-platform">Canal</label><select id="post-platform" name="platform">${['Instagram','Facebook','Web'].map(f=>`<option ${p?.platform===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label for="post-date">Fecha prevista</label><input type="date" id="post-date" name="date" required value="${p?.date||'2026-10-14'}"></div><div class="field wide"><label for="post-cta">Llamada a la acción</label><input id="post-cta" name="cta" required maxlength="180" value="${esc(p?.cta||state.profile.cta)}"></div></div><div class="form-actions">${button('Cancelar','close','type="button" data-close-dialog')}${button('Guardar borrador','check','type="submit"','primary')}</div></form>`);document.getElementById('post-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),updated={title:fd.get('title').trim(),hook:fd.get('hook').trim(),copy:fd.get('copy').trim(),campaign:fd.get('campaign'),format:fd.get('format'),platform:fd.get('platform'),date:fd.get('date'),cta:fd.get('cta').trim(),status:'Borrador',approval:null,feedback:''};if(p){p.versions=p.versions||[];p.versions.push({...p,versions:undefined});Object.assign(p,updated,{version:p.version+1});log(`Nueva versión ${p.version}: ${p.title}; aprobación invalidada.`);}else{state.posts.unshift({...updated,id:`post-${Date.now()}`,version:1,owner:state.role==='admin'?'Gonza':'Usuario de marca',color:'purple',pillar:'Propuesta de contenido'});log('Nueva pieza preparada.');}closeDialog();render();toast('Borrador guardado. La aprobación requiere revisar esta versión.');});}
function changesPost(id){const p=state.posts.find(x=>x.id===id);openDialog('Solicitar cambios',`<p>La revisión se registra sobre la versión ${p.version} de «${esc(p.title)}».</p><form id="changes-form"><div class="field"><label for="feedback">¿Qué debemos ajustar?</label><textarea id="feedback" name="feedback" required maxlength="1000" placeholder="Explica el cambio y su objetivo."></textarea></div><div class="form-actions">${button('Guardar revisión','check','type="submit"','primary')}</div></form>`);document.getElementById('changes-form').addEventListener('submit',e=>{e.preventDefault();p.feedback=new FormData(e.target).get('feedback').trim();p.status='Borrador';p.approval=null;log(`Cambios solicitados para ${p.title}, versión ${p.version}.`);postDetail(id);render();toast('Cambios registrados en la demo.');});}
function publishPost(id){const p=state.posts.find(x=>x.id===id);if(state.role!=='admin'||p.status!=='Aprobado')return;openDialog('Registrar publicación manual',`<p>El registro deja evidencia de una publicación que ya realizaste. Este prototipo no publica contenido.</p><form id="publish-form"><div class="form-grid"><div class="field wide"><label for="publication-url">Enlace de la publicación</label><input type="url" id="publication-url" name="url" required placeholder="https://..."></div><div class="field"><label for="publication-date">Fecha real</label><input type="date" id="publication-date" name="date" value="${DEMO_DATE}" required></div></div><div class="form-actions">${button('Registrar en la demo','check','type="submit"','primary')}</div></form>`);document.getElementById('publish-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);const url=new URL(fd.get('url'));if(!['http:','https:'].includes(url.protocol)){toast('Utiliza un enlace web válido.');return;}p.url=url.href;p.date=fd.get('date');p.status='Publicado';log(`Publicación manual registrada para ${p.title}.`);closeDialog();render();toast('Publicación registrada; no se realizó ningún envío.');});}
function ideas(){openDialog('Tres ángulos para abrir conversación',`<p>Plantillas de ideación basadas en el perfil de la marca. No se utiliza un modelo de IA conectado en esta demo.</p>${[['El problema','¿Qué pasa después de que alguien pide información?','Educación'],['La demostración','De un mensaje suelto a un siguiente paso visible.','Demostración'],['La prueba','Qué revisamos para que una página explique mejor tu servicio.','Proceso y confianza']].map(([title,text,pillar])=>`<div class="metric-definition"><small>${pillar.toUpperCase()}</small><strong>${title}</strong><p>${text}</p>${button('Preparar este borrador','plus',`data-idea="${esc(text)}"`,'link')}</div>`).join('')}<p class="footnote">Revisar adecuación a público, oferta y canal antes de aprobar.</p>`,'VECTOR / ASISTENCIA CONTEXTUAL');}

function inbox(){const pending=state.leads.filter(l=>!l.contacted),threads=[...pending,...state.leads.filter(l=>l.contacted)].slice(0,12);const current=state.leads.find(l=>l.id===state.selectedThread)||threads[0];if(!current)return heading('Conversaciones','No hay contactos en este filtro.');const msgs=state.messages[current.id]||[{direction:'in',text:`Hola, me interesa conocer su servicio de ${current.need.toLowerCase()}. ¿Cuál sería el siguiente paso?`,time:'Consulta de ejemplo'}];return `${heading('Cada conversación tiene dirección.','Contexto, responsable y siguiente paso en una sola bandeja.',button('Registrar contacto','plus','data-new-lead','primary'),'VECTOR / ATENCIÓN Y COMUNIDAD')}<div class="metric-note">Canales simulados · Los mensajes se registran solo en tu navegador · ${state.profile.sla} min como objetivo interno de demo</div><div class="inbox"><div class="inbox-list"><div class="inbox-label">PRIORIDAD: ${pending.length} SIN INTERCAMBIO CONFIRMADO</div>${threads.map(l=>`<button class="thread-button ${l.id===current.id?'selected':''}" data-thread="${l.id}"><span class="mini-avatar">${initials(l.name)}</span><div class="thread-data"><div class="thread-name"><strong>${esc(l.name)}</strong><small>${shortDate(l.date)}</small></div><p>${esc(l.need)} · ${esc(l.company)}</p>${badge(l.contacted?'Atendida':l.owner==='Sin asignar'?'Sin responsable':'Por contactar',l.contacted?'green':'orange')}</div></button>`).join('')}</div><section class="chat-panel"><div class="chat-header"><div><strong>${esc(current.name)}</strong><small>${esc(current.company)} · ${sourceName(current.source)} · Demo</small></div>${button('Abrir ficha','users',`data-lead="${current.id}"`)}</div><div class="chat-context"><span>Necesidad: <strong>${esc(current.need)}</strong></span><span>Responsable: <strong>${esc(current.owner)}</strong></span></div><div class="chat-messages">${msgs.map(msg=>`<div class="message ${msg.direction==='out'?'outgoing':''}">${esc(msg.text)}<small>${esc(msg.time)}</small></div>`).join('')}</div><form class="chat-compose" id="reply-form"><label class="sr-only" for="reply-message">Respuesta de prueba</label><textarea id="reply-message" required maxlength="2000" placeholder="Escribe una respuesta útil o prepara una sugerencia…"></textarea><div class="compose-actions"><button type="button" class="button purple" data-draft-reply="${current.id}">${ico('sparkle')} Preparar respuesta</button><div class="button-row"><small>No se envía a ningún canal.</small>${button('Registrar respuesta de prueba','check','type="submit"','primary')}</div></div></form></section></div>`;}
function crm(){const leads=filteredLeads().filter(l=>(leadCampaign==='all'||l.campaign===leadCampaign)&&(leadFilter==='all'||l.stage===leadFilter)&&(!searchQuery||`${l.name} ${l.company} ${l.need}`.toLowerCase().includes(searchQuery.toLowerCase())));const m=aggregate();return `${heading('Del interés a una oportunidad.','Una persona puede tener varias necesidades. Cada oportunidad conserva su responsable y siguiente acción.',`${button('Exportar demo','download','data-export="leads"')}${button('Nuevo contacto','plus','data-new-lead','primary')}`,'VECTOR / SEGUIMIENTO COMERCIAL')}<div class="kpi-grid">${kpi('Oportunidades abiertas',m.leads.filter(l=>!['Ganado','Perdido'].includes(l.stage)).length,'Con necesidad registrada','opportunities')}${kpi('Sin próxima acción',m.leads.filter(l=>!l.next&&!['Ganado','Perdido'].includes(l.stage)).length,'Pendientes por completar','next')}${kpi('Valor de pipeline',money(m.leads.filter(l=>!['Ganado','Perdido'].includes(l.stage)).reduce((sum,l)=>sum+l.value,0)),'Valor estimado · no ingreso','pipeline')}${kpi('Cierre de resueltas',pct(m.won.length,m.won.length+m.lost.length),'Ganadas / (ganadas + perdidas)','closing')}</div>${leadCampaign!=='all'?`<div class="metric-note">Campaña: ${esc(state.campaigns.find(c=>c.id===leadCampaign)?.name||'')} <button data-clear-campaign>Quitar filtro ×</button></div>`:''}<div class="toolbar"><label class="input-search">${ico('search')}<input id="lead-search" aria-label="Buscar prospectos" placeholder="Nombre, empresa o necesidad" value="${esc(searchQuery)}"></label><div class="button-row">${filters()}<select class="select" id="lead-filter" aria-label="Filtrar etapa"><option value="all">Todas las etapas</option>${stages.map(s=>`<option ${leadFilter===s?'selected':''}>${s}</option>`).join('')}</select><div class="tabs" style="margin:0;border:0"><button class="${state.crmMode==='pipeline'?'active':''}" data-crm-mode="pipeline">Pipeline</button><button class="${state.crmMode==='list'?'active':''}" data-crm-mode="list">Lista</button></div></div></div>${state.crmMode==='pipeline'?`<div class="kanban">${stages.map(stage=>`<section class="kanban-column"><div class="kanban-heading">${stage}<span class="muted">${leads.filter(l=>l.stage===stage).length}</span></div>${leads.filter(l=>l.stage===stage).map(l=>`<button class="deal-card" data-lead="${l.id}"><strong>${esc(l.name)}</strong><p>${esc(l.company)} · ${esc(l.need)}</p><b>${money(l.value)}</b><small>${esc(l.owner)}</small><small class="${!l.next?'no-next':''}">${l.next?esc(l.next):['Ganado','Perdido'].includes(stage)?'Decisión registrada':'⚑ Sin próxima acción'}</small></button>`).join('')}</section>`).join('')}</div>`:leadTable(leads)}<p class="footnote">Fixture de una oportunidad por contacto; la evolución del modelo admite varias oportunidades por necesidad. Las etapas y decisiones se guardan localmente.</p>`;}
function leadTable(leads){return `<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Contacto / empresa</th><th>Etapa</th><th>Origen</th><th>Responsable</th><th>Próxima acción</th><th>Valor estimado</th><th></th></tr></thead><tbody>${leads.map(l=>`<tr><td><div class="table-person"><span class="mini-avatar">${initials(l.name)}</span><div><strong>${esc(l.name)}</strong><small>${esc(l.company)}</small></div></div></td><td>${badge(l.stage)}</td><td>${sourceName(l.source)}</td><td>${esc(l.owner)}</td><td>${l.next?esc(l.next):'<span class="warning">Sin próxima acción</span>'}</td><td>${money(l.value)}</td><td><button data-lead="${l.id}">Abrir ↗</button></td></tr>`).join('')}</tbody></table></div><div class="table-foot">${leads.length} registros · Datos ficticios · Sin información personal real</div></section>`;}
function leadDetail(id){const l=state.leads.find(x=>x.id===id);if(!l)return;openDialog(l.name,`<p>${esc(l.company)} · ${esc(l.need)}</p><div class="button-row">${badge(l.stage)}<span class="source-label">${sourceName(l.source)} · origen registrado en demo</span></div><div class="detail-grid"><div class="detail-item">Campaña<strong>${esc(state.campaigns.find(c=>c.id===l.campaign)?.name||'Sin atribuir a una campaña')}</strong></div><div class="detail-item">Contacto confirmado<strong>${l.contacted?'Intercambio bidireccional registrado':'Pendiente de confirmar'}</strong></div></div><form id="lead-update"><div class="form-grid"><div class="field"><label for="lead-owner">Responsable</label><select name="owner" id="lead-owner">${['Sin asignar','Karloz','Alexandra','Gonza','Usuario de marca'].map(o=>`<option ${l.owner===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="field"><label for="lead-stage">Etapa</label><select name="stage" id="lead-stage">${stages.map(s=>`<option ${l.stage===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field wide"><label for="lead-next">Siguiente acción</label><input name="next" id="lead-next" value="${esc(l.next)}" maxlength="200" placeholder="Qué vamos a hacer y para qué"></div><div class="field"><label for="lead-next-date">Fecha de siguiente acción</label><input type="date" name="nextDate" id="lead-next-date" value="${l.nextDate||'2026-10-14'}"></div><div class="field"><label for="lead-value">Valor estimado / venta ganada (MXN)</label><input name="value" id="lead-value" type="number" min="0" max="10000000" step="1" value="${l.value}" required></div><div class="field"><label for="lead-close-date">Fecha de cierre (si aplica)</label><input type="date" name="closedAt" id="lead-close-date" value="${l.closedAt||DEMO_DATE}"></div><div class="field"><label for="lead-lost-reason">Motivo de pérdida (si aplica)</label><input name="lostReason" id="lead-lost-reason" maxlength="200" value="${esc(l.lostReason)}"></div><div class="field wide"><label for="lead-note">Nota de seguimiento</label><textarea name="note" id="lead-note" maxlength="1000" placeholder="Registrar contexto o acuerdo"></textarea></div></div><div class="form-actions">${button('Confirmar contacto bidireccional','check',`type="button" data-confirm-contact="${id}"`)}${button('Guardar seguimiento','check','type="submit"','primary')}</div><p class="footnote">Un mensaje enviado no confirma contacto. Marca intercambio solo con una respuesta real; aquí exploras datos ficticios.</p></form><div class="separator"></div><h3>Historial de la oportunidad</h3>${l.history.slice().reverse().map(h=>`<div class="timeline-item"><small>${esc(h.date)}</small>${esc(h.text)}</div>`).join('')}`,'VECTOR / CONTEXTO Y SIGUIENTE PASO');document.getElementById('lead-update').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),stage=fd.get('stage'),owner=fd.get('owner'),next=fd.get('next').trim(),reason=fd.get('lostReason').trim();if(!['Ganado','Perdido'].includes(stage)&&(owner==='Sin asignar'||!next||!fd.get('nextDate'))){toast('Una oportunidad abierta necesita responsable, próxima acción y fecha.');return;}if(stage==='Perdido'&&!reason){toast('Registra el motivo de pérdida.');return;}if(['Ganado','Perdido'].includes(stage)&&!fd.get('closedAt')){toast('Registra la fecha de cierre.');return;}const old=l.stage;Object.assign(l,{stage,owner,next,nextDate:fd.get('nextDate'),value:Number(fd.get('value')),closedAt:['Ganado','Perdido'].includes(stage)?fd.get('closedAt'):'',lostReason:stage==='Perdido'?reason:''});if(['Calificado','Propuesta','Ganado'].includes(stage))l.qualified=true;if(stage!=='Ganado')l.attributedValue=0;if(old!=='Ganado'&&stage==='Ganado')l.attributedValue=0;l.history.push({date:DEMO_DATE,text:`${old!==stage?old+' → '+stage+' · ':''}Seguimiento actualizado por ${state.role==='admin'?'Administrador':'Usuario'}${fd.get('note').trim()?' · '+fd.get('note').trim():''}`});log(`Seguimiento guardado: ${l.name} · ${stage}`);closeDialog();render();toast(stage==='Ganado'?'Venta guardada; atribución pendiente de evidencia.':'Seguimiento guardado en la demo.');});}
function leadForm(){openDialog('Registrar un contacto',`<p>Una necesidad concreta, un responsable y un siguiente paso. No introduzcas datos personales reales en este prototipo.</p><form id="new-lead-form"><div class="form-grid"><div class="field"><label for="new-name">Nombre de ejemplo</label><input id="new-name" name="name" maxlength="100" required></div><div class="field"><label for="new-company">Empresa</label><input id="new-company" name="company" maxlength="100" required></div><div class="field wide"><label for="new-need">Necesidad</label><input id="new-need" name="need" maxlength="200" required></div><div class="field"><label for="new-source">Origen registrado</label><select id="new-source" name="source"><option value="meta">Meta</option><option value="google">Google</option><option value="direct">Directo / referido / desconocido</option></select></div><div class="field"><label for="new-owner">Responsable</label><select id="new-owner" name="owner"><option>Karloz</option><option>Alexandra</option><option>Gonza</option><option>Usuario de marca</option></select></div><div class="field wide"><label for="new-next">Siguiente acción</label><input id="new-next" name="next" required maxlength="200" placeholder="Contactar para entender su necesidad"></div><div class="field"><label for="new-nextdate">Fecha</label><input type="date" id="new-nextdate" name="nextDate" value="2026-10-14" required></div><div class="field"><label for="new-value">Valor estimado (MXN)</label><input type="number" min="0" max="10000000" id="new-value" name="value" value="0" required></div></div><div class="form-actions">${button('Registrar contacto','check','type="submit"','primary')}</div></form>`);document.getElementById('new-lead-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);state.leads.unshift({id:`lead-${Date.now()}`,name:fd.get('name').trim(),company:fd.get('company').trim(),need:fd.get('need').trim(),source:fd.get('source'),campaign:'',stage:'Nuevo',owner:fd.get('owner'),next:fd.get('next').trim(),nextDate:fd.get('nextDate'),value:Number(fd.get('value')),date:DEMO_DATE,contacted:false,responseMinutes:null,qualified:false,closedAt:'',lostReason:'',attributedValue:0,notes:[],history:[{date:DEMO_DATE,text:'Registro manual de demostración · Sin atribución automática'}]});log('Nuevo contacto de prueba registrado.');closeDialog();render();toast('Contacto registrado con responsable y siguiente acción.');});}

function results(){const m=aggregate(state.resultsTab==='meta'?'meta':state.resultsTab==='google'?'google':state.channel);const tabs=[['business','Avance comercial'],['meta','Meta Business'],['google','Google y web'],['quality','Calidad de datos']];return `${heading('Resultados que orientan decisiones.','Cada indicador tiene definición, fuente y límite. La evidencia está a un clic.',`${filters(!['meta','google'].includes(state.resultsTab))}${button('Exportar reporte','download','data-export="report"')}`,'VECTOR / INTELIGENCIA COMERCIAL')}<div class="tabs" role="tablist" aria-label="Lecturas de resultados">${tabs.map(([key,title])=>`<button role="tab" id="result-tab-${key}" aria-controls="results-panel" aria-selected="${state.resultsTab===key}" class="${state.resultsTab===key?'active':''}" data-results-tab="${key}">${title}</button>`).join('')}</div><div id="results-panel" role="tabpanel" aria-labelledby="result-tab-${state.resultsTab}">${state.resultsTab==='business'?businessResults(m):state.resultsTab==='meta'?metaResults(m):state.resultsTab==='google'?googleResults(m):qualityResults(m)}</div>`;}
function businessResults(m){return `<div class="kpi-grid">${kpi('Inversión publicitaria',money(m.spend),'Suma del gasto de campañas','spend','Campañas demo')}${kpi('Costo por calificado',m.qualifiedAttributed.length?money(m.spend/m.qualifiedAttributed.length):'No calculable','Gasto / calificados atribuibles del fixture','cpql')}${kpi('Ventas ganadas',money(m.revenue),'Ingreso comercial confirmado en demo','revenue')}${kpi('ROAS comercial',m.spend?(m.attributed/m.spend).toFixed(2)+'x':'No calculable','Ventas atribuidas / inversión','roas')}</div><div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-head"><div><h2>Qué avanzó y qué falta</h2><p>Misma cohorte de captación · ${state.period==='7'?'7–13 oct':'14 sep–13 oct'}</p></div>${button('Ver registros','arrow','data-view="crm"')}</div>${funnel()}<div class="metric-row"><span>Cierre de oportunidades resueltas<small>Abiertas se muestran aparte</small></span><b>${pct(m.won.length,m.won.length+m.lost.length)}</b></div><div class="metric-row"><span>Oportunidades aún abiertas</span><b>${m.leads.length-m.won.length-m.lost.length}</b></div><div class="metric-row"><span>ROI / rentabilidad<small>Faltan costos y margen</small></span><b style="font-size:14px">No calculable</b></div></section><section class="panel panel-pad"><div class="panel-head"><h2>Atribución visible, límites claros</h2>${ico('info')}</div><div class="metric-row"><span>Venta vinculada a publicidad<small>Crédito CRM de ejemplo</small></span><b>${money(m.attributed)}</b></div><div class="metric-row"><span>Venta sin crédito atribuido<small>Se conserva dentro del total comercial</small></span><b>${money(m.revenue-m.attributed)}</b></div><p class="footnote">Regla propuesta: ${esc(state.profile.attribution)}. No se ejecuta un motor real de atribución. La cifra nativa de Meta o GA4 no reemplaza el total de ventas del CRM.</p><div class="insight"><h3>${ico('sparkle')} Revisión sugerida</h3><p>Completa origen y evidencia de las oportunidades antes de decidir cuánto invertir. Evita sumar la misma venta atribuida por dos plataformas.</p>${button('Preparar revisión de atribución','plus','data-create-task="Reconciliar atribución de campañas con ventas CRM"','link')}</div></section></div><section class="panel"><div class="panel-pad"><h2 style="font-size:15px">Resultados por campaña</h2><p class="footnote">La tabla conserva el gasto completo de cada campaña; el resumen superior respeta los filtros del periodo.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Campaña</th><th>Canal</th><th>Inversión</th><th>Captaciones</th><th>Calificados</th><th>Ganadas</th><th>Venta atribuida</th></tr></thead><tbody>${activeCampaigns().map(c=>{const leads=state.leads.filter(l=>l.campaign===c.id);return `<tr><td><button data-campaign="${c.id}">${esc(c.name)}</button></td><td>${sourceName(c.channel)}</td><td>${money(c.spend)}</td><td>${leads.length}</td><td>${leads.filter(l=>l.qualified).length}</td><td>${leads.filter(l=>l.stage==='Ganado').length}</td><td>${money(leads.filter(l=>l.stage==='Ganado').reduce((s,l)=>s+l.attributedValue,0))}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function metaResults(m){const f=state.period==='7'?.28:1,read=state.metaRead||'all',base=read==='organic'?[42100,53100,720]:read==='paid'?[56200,73200,1460]:[84200,126300,2180];const reach=Math.round(base[0]*f),impressions=Math.round(base[1]*f),clicks=Math.round(base[2]*f);return `<div class="toolbar"><span class="muted" style="font-size:11px">Contenido orgánico y publicidad, en lecturas distintas.</span><label><span class="sr-only">Tipo de distribución Meta</span><select class="select" id="meta-read"><option value="all" ${read==='all'?'selected':''}>Total nativo de Meta</option><option value="organic" ${read==='organic'?'selected':''}>Orgánico</option><option value="paid" ${read==='paid'?'selected':''}>Pagado</option></select></label></div><div class="metric-note">Meta Business Suite / Ads · Dataset ficticio · Las métricas nativas se mantienen separadas de personas únicas del CRM</div><div class="kpi-grid">${kpi('Alcance en Meta',num(reach),'No sumar como personas únicas entre redes','reach','Meta demo')}${kpi('Impresiones',num(impressions),'Exposiciones, incluidas repeticiones','impressions','Meta demo')}${kpi('CTR de enlace',pct(clicks,impressions),'Clics de enlace / impresiones','ctr','Meta demo')}${kpi('Frecuencia',(impressions/reach).toFixed(2),'Contexto, no umbral universal','frequency','Meta demo')}</div><div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-head"><h2>Contenido que genera interés</h2>${button('Abrir estudio','arrow','data-view="content"')}</div>${[['Guardados',Math.round(184*f),'Señal de utilidad; no equivale a intención de compra'],['Compartidos',Math.round(96*f),'Distribución e interés; revisar contexto'],['Clics de enlace',clicks,'Acción previa a la experiencia web'],['Contactos CRM · Todo Meta',m.leads.filter(l=>l.source==='meta').length,'Universo CRM de la cohorte, independiente del filtro nativo']].map(([name,value,note])=>`<div class="metric-row"><span>${name}<small>${note}</small></span><b>${num(value)}</b></div>`).join('')}</section><section class="panel panel-pad"><h2 style="font-size:15px">Lo que conviene revisar</h2><div class="insight"><h3>${ico('lab')} Una hipótesis, una prueba</h3><p>Si el costo sube y las consultas calificadas caen, revisa oferta, público, atención y medición. Frecuencia alta o CTR bajo no prueban fatiga por sí solos.</p>${button('Diseñar prueba de mensaje','arrow','data-view="lab"','purple')}</div><p class="footnote">No existe una frecuencia «buena» ni un CTR objetivo universal. Comparar formato, objetivo, periodo y calidad comercial.</p><a class="source-link" href="https://about.fb.com/ltam/wp-content/uploads/sites/14/2023/11/LeadGenerationGuide.pdf" target="_blank" rel="noopener">Guía oficial de Meta ↗</a></section></div>`;}
function googleResults(m){const f=state.period==='7'?.28:1;const sessions=Math.round(2610*f),impressions=Math.round(26400*f),clicks=Math.round(1140*f),calls=Math.round(34*f);return `<div class="metric-note">Tres fuentes diferentes: Search Console · Business Profile · Google Analytics 4. No mezclar sus universos.</div><div class="kpi-grid">${kpi('Clics desde búsqueda',num(clicks),'Clics del sitio en resultados','searchclicks','Search Console demo')}${kpi('CTR de búsqueda',pct(clicks,impressions),'Clics / impresiones del sitio','searchctr','Search Console demo')}${kpi('Sesiones en la web',num(sessions),'Todas las fuentes de ejemplo','sessions','GA4 demo')}${kpi('Clics para llamar',calls,'No representan llamadas conectadas','calls','Business Profile demo')}</div><div class="flow-grid"><section class="panel panel-pad"><div class="panel-head"><div><h2>Búsqueda con intención</h2><p>Consultas ficticias · Search Console</p></div>${ico('search')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Consulta</th><th>Impresiones</th><th>Clics</th><th>CTR</th></tr></thead><tbody>${[['agencia de marketing para empresas',6200,225],['diseño web para servicios',5100,198],['manejo de redes sociales',7400,260],['vector inside',2500,320]].map(([q,i,c])=>`<tr><td>${q}</td><td>${num(Math.round(i*f))}</td><td>${num(Math.round(c*f))}</td><td>${pct(c,i)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Muestra parcial de consultas, no suma del total. Priorizar relevancia del servicio; ninguna mejora garantiza ranking.</p></section><section class="panel panel-pad"><div class="panel-head"><h2>Presencia local que facilita contacto</h2>${ico('location')}</div><p class="muted" style="font-size:11px">Checklist propio inspirado en las prácticas oficiales de Google, no una puntuación del algoritmo.</p><div class="checklist">${[['Datos y categoría coherentes','Nombre, servicio y contacto correctos'],['Perfil verificado','Comprobar titular y permisos'],['Horarios vigentes','Incluye horarios especiales'],['Servicios y descripción claros','Conectar oferta y necesidad'],['Fotos y evidencia actualizadas','Mostrar el trabajo autorizado'],['Gestión de reseñas','Responder con contexto y respeto']].map(([title,sub],i)=>`<label class="check-item"><input type="checkbox" data-google-check="${i}" ${state.googleChecks[i]?'checked':''}><span>${title}<small>${sub}</small></span></label>`).join('')}</div><a class="source-link" href="https://support.google.com/business/answer/7091?hl=es" target="_blank" rel="noopener">Buenas prácticas oficiales ↗</a></section></div><div class="section-heading"><h2>Eventos que representan el recorrido</h2>${button('Preparar plan de medición','plus','data-create-task="Validar generate_lead y eventos de contacto en GA4"','link')}</div><section class="panel"><div class="table-wrap"><table class="data-table table-sources"><thead><tr><th>Evento</th><th>Cuándo registrarlo</th><th>Qué evita</th></tr></thead><tbody>${[['contact_intent','Clic a WhatsApp, teléfono o canal. Evento propio propuesto.','Contar el clic como conversación.'],['generate_lead','Cuando se confirma una captura válida.','Contar formularios fallidos o simples visitas.'],['working_lead','Al empezar a trabajar el lead, según definición instrumentada.','Confundir trabajo comercial con venta.'],['qualify_lead','Al confirmar que cumple criterios de calificación.','Asignar calidad automáticamente por haber escrito.'],['close_convert_lead','Al convertir el lead en cliente según evidencia CRM.','Prometer ingresos a partir de clics.']].map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="table-foot">GA4 y CRM pueden contar universos distintos. No enviar datos personales a Analytics ni incluirlos en UTM.</div></section>`;}
function qualityResults(m){const identified=m.leads.filter(l=>l.campaign).length;return `<div class="kpi-grid">${kpi('Campaña identificada',pct(identified,m.leads.length),`${identified} de ${m.leads.length} registros`,'attribution')}${kpi('Sin campaña atribuida',m.leads.length-identified,'Se conserva el origen declarado','attribution')}${kpi('Fuentes reales conectadas',0,'Este prototipo no accede a cuentas','connections','Estado real')}${kpi('Próxima acción faltante',m.leads.filter(l=>!l.next&&!['Ganado','Perdido'].includes(l.stage)).length,'Bloqueo operativo visible','next')}</div><section class="panel panel-pad"><div class="panel-head"><h2>Estado y alcance de cada fuente</h2>${state.role==='admin'?button('Configurar fuentes','plug','data-view="connections"'):''}</div>${['Meta Business Suite / Ads','GA4','Search Console','Google Business Profile','CRM de la demo'].map(name=>`<div class="metric-row"><span>${name}<small>${name.includes('CRM')?'Persistencia local en este navegador':'Valores ficticios para diseñar el recorrido'}</small></span>${badge(name.includes('CRM')?'Local':'Sin conexión real',name.includes('CRM')?'green':'orange')}</div>`).join('')}<p class="footnote">Actualización del fixture: 13 octubre 2026. No hay sincronización. Cambiar un perfil o marcar el checklist no otorga acceso a ninguna plataforma.</p></section>`;}

function lab(){return `${heading('Probar. Aprender. Corregir trayectoria.','Una hipótesis clara, una señal principal y una decisión que conserve su evidencia.',button('Nueva hipótesis','plus','data-new-experiment','primary'),'VECTOR / LABORATORIO DE CRECIMIENTO')}<div class="research-banner"><h3>La mejor práctica es empezar con una pregunta útil.</h3><p>Compara rutas y mensajes con calidad de consulta. Mantén el contexto del periodo y evita declarar un ganador con una muestra insuficiente.</p></div><div class="lab-grid">${state.experiments.map(e=>`<article class="panel experiment">${badge(e.status,'purple')}<h3>${esc(e.name)}</h3><p>${esc(e.hypothesis)}</p><div class="metric-note">Señal principal: ${esc(e.primary)}</div><div class="experiment-values"><div>VARIANTE A<br>${esc(e.a)}<b>${e.aSessions?pct(e.aQualified,e.aSessions):'Sin datos'}</b><small>${e.aQualified} calificados / ${e.aSessions} sesiones</small></div><div>VARIANTE B<br>${esc(e.b)}<b>${e.bSessions?pct(e.bQualified,e.bSessions):'Sin datos'}</b><small>${e.bQualified} calificados / ${e.bSessions} sesiones</small></div></div><p>No hay ganador validado. Son valores ficticios, no un experimento estadístico ejecutado.</p>${button('Registrar aprendizaje','edit',`data-experiment="${e.id}"`)}${e.learning?`<p class="metric-note">Aprendizaje: ${esc(e.learning)}</p>`:''}</article>`).join('')}</div><div class="section-heading"><h2>Convertir una señal en trabajo</h2></div><div class="compact-grid">${[['Clics sin contactos','Revisar landing, oferta, formulario y medición antes de subir presupuesto.','Revisar fricción en landing y formulario'],['Consultas sin avance','Revisar pertinencia, capacidad de atención y siguientes acciones.','Evaluar calidad de consultas y seguimiento']].map(([title,copy,task])=>`<section class="panel panel-pad"><h3>${title}</h3><p class="footnote">${copy}</p>${button('Crear una tarea','plus',`data-create-task="${task}"`,'link')}</section>`).join('')}</div>`;}
function newExperiment(){openDialog('Preparar una hipótesis',`<form id="experiment-form"><div class="form-grid"><div class="field wide"><label for="experiment-name">Nombre</label><input id="experiment-name" name="name" required maxlength="100"></div><div class="field wide"><label for="experiment-hypothesis">Hipótesis y contexto</label><textarea id="experiment-hypothesis" name="hypothesis" required maxlength="700"></textarea></div><div class="field"><label for="experiment-a">Variante A</label><input id="experiment-a" name="a" required maxlength="160"></div><div class="field"><label for="experiment-b">Variante B</label><input id="experiment-b" name="b" required maxlength="160"></div><div class="field wide"><label for="experiment-primary">Señal principal para revisar</label><input id="experiment-primary" name="primary" required maxlength="180" placeholder="Leads calificados por sesión"></div></div><div class="form-actions">${button('Guardar hipótesis','check','type="submit"','primary')}</div></form>`);document.getElementById('experiment-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);state.experiments.push({id:`exp-${Date.now()}`,name:fd.get('name').trim(),hypothesis:fd.get('hypothesis').trim(),a:fd.get('a').trim(),b:fd.get('b').trim(),primary:fd.get('primary').trim(),status:'Por preparar',aSessions:0,aQualified:0,bSessions:0,bQualified:0});log('Hipótesis registrada.');closeDialog();render();toast('Hipótesis guardada para una prueba futura.');});}

function profile(){const p=state.profile;return `${heading('El contexto de la marca orienta el trabajo.','La oferta, el público y el tono acompañan campañas, borradores y seguimiento.',button('Ver sitio de referencia','link','data-open-website'),'VECTOR / ADN DE MARCA')}<div class="profile-banner"><img src="assets/vector-isotype.png" alt="Isotipo Vector Inside"><div><h2>Vector Inside</h2><p>Presencia → captación → conversación → seguimiento → resultado.</p></div>${badge('Operación interna','lime')}</div><form id="profile-form" class="panel panel-pad"><div class="form-grid"><div class="field"><label for="brand-name">Nombre</label><input id="brand-name" name="name" required maxlength="100" value="${esc(p.name)}"></div><div class="field"><label for="brand-website">Sitio web</label><input id="brand-website" name="website" type="url" required value="${esc(p.website)}"></div><div class="field wide"><label for="brand-offer">Oferta y narrativa</label><textarea id="brand-offer" name="offer" required maxlength="700">${esc(p.offer)}</textarea></div><div class="field wide"><label for="brand-audience">Público y necesidad</label><textarea id="brand-audience" name="audience" required maxlength="700">${esc(p.audience)}</textarea></div><div class="field wide"><label for="brand-tone">Cómo habla la marca</label><textarea id="brand-tone" name="tone" required maxlength="700">${esc(p.tone)}</textarea></div><div class="field"><label for="brand-cta">Llamada a la acción</label><input id="brand-cta" name="cta" maxlength="180" required value="${esc(p.cta)}"></div><div class="field"><label for="brand-goal">Objetivo principal</label><input id="brand-goal" name="goal" maxlength="180" required value="${esc(p.goal)}"></div><div class="field"><label for="brand-sla">Objetivo de respuesta (minutos hábiles)</label><input id="brand-sla" name="sla" type="number" min="1" max="1440" required value="${p.sla}"><small>Política propia, ajustable a capacidad. No es benchmark.</small></div><div class="field"><label for="brand-hours">Horario de atención</label><input id="brand-hours" name="hours" maxlength="200" required value="${esc(p.hours)}"></div></div><div class="form-actions">${button('Guardar perfil de demostración','check','type="submit"','primary')}</div></form><div class="section-heading"><h2>Sistema visual de la marca</h2></div><div class="source-grid"><section class="source-card"><h3>Negro estructural</h3><p>#080808 · Fondos y estructura de la interfaz, inspirado en el sitio actual.</p></section><section class="source-card"><h3>Lima Vector</h3><p>#C3F400 · Acciones principales y señales de atención. La marca se reconoce sin saturar la lectura.</p></section><section class="source-card"><h3>Morado / azul de apoyo</h3><p>Inteligencia, comparación y contexto. Estados siempre acompañados de texto.</p></section></div>`;}
const connectionData=[['Meta Business Suite','meta','Contenido, resultados y bandeja cuando las cuentas y permisos lo permitan.','Página / cuenta de Instagram, acceso por persona, autorización oficial y contrato de métricas.'],['Google Analytics 4','google','Sesiones, intenciones de contacto y eventos de lead en la web.','Propiedad GA4, eventos verificados, exclusión de datos personales y permisos de lectura.'],['Google Search Console','google','Consultas y páginas que generan descubrimiento desde búsqueda.','Propiedad verificada, permisos y filtros por consulta, página y dispositivo.'],['Google Business Profile','google','Interacciones con el perfil del negocio en Search y Maps.','Perfil elegible/verificado, permisos y definiciones nativas. Clic para llamar no acredita una llamada.'],['Captación web / CSV','instagram','Capturas válidas, origen y reconciliación con contactos del CRM.','Validación, deduplicación por evento, vista previa por fila e historial de importación.'],['Mensajería y WhatsApp','meta','Conversaciones, transferencia humana y seguimiento según autorización.','Proveedor y permisos oficiales, reglas de envío aplicables y acuse verificable.']];
function connections(){return `${heading('Fuentes claras. Integraciones graduales.','Explora lo que requiere cada conexión. Ninguna cuenta externa está conectada en este prototipo.',button('Crear enlace UTM','link','data-utm','primary'),'VECTOR / FUENTES Y CONFIANZA')}<div class="metric-note">Estado real: 0 conexiones externas. No se solicitan contraseñas ni tokens en esta demo.</div><div class="connection-grid">${connectionData.map(([name,icon,desc],i)=>`<section class="panel connection-card"><div class="source-top"><span class="platform-icon ${icon}">${icon==='google'?'G':icon==='meta'?'∞':'↗'}</span><h3>${name}</h3></div>${badge('Sin conexión real','orange')}<p>${desc}</p>${button('Ver plan de conexión','arrow',`data-connection="${i}"`)}</section>`).join('')}</div><div class="section-heading"><h2>Importación y calidad</h2></div><section class="panel panel-pad"><div class="panel-head"><div><h2>Un CSV puede iniciar el piloto</h2><p>Mapeo, preview, errores por fila y repetición sin duplicados.</p></div>${button('Explorar importación CSV','file','data-import','primary')}</div><p class="footnote">La demo permite previsualizar e importar contactos de ejemplo con validación simple. La deduplicación de producción requiere IDs y un modelo persistente seguro.</p></section>`;}
function team(){return `${heading('Dos perfiles. Responsabilidades claras.','El Administrador prepara y configura. El Usuario revisa, colabora y decide dentro de su alcance.',button('Restablecer datos demo','settings','data-reset'),'VECTOR / EQUIPO Y CONTROL')}<div class="compact-grid"><section class="panel panel-pad"><div class="source-top"><span class="avatar">KV</span><h2>Administrador</h2>${badge('Demo','purple')}</div><p class="footnote">Prepara campañas y piezas, organiza conversaciones y CRM, configura marca y medición, consulta resultados y registra publicaciones manuales.</p><div class="checklist"><span class="check-item">${ico('check')} Gestionar operación y responsables</span><span class="check-item">${ico('check')} Configurar fuentes y objetivo de atención</span><span class="check-item">${ico('check')} Acceder al registro de cambios</span></div></section><section class="panel panel-pad"><div class="source-top"><span class="avatar">VI</span><h2>Usuario</h2>${badge('Demo','purple')}</div><p class="footnote">Consulta resultados, revisa y aprueba versiones, propone campañas y colabora en el seguimiento de los contactos de su espacio.</p><div class="checklist"><span class="check-item">${ico('check')} Revisar, comentar y aprobar contenido</span><span class="check-item">${ico('check')} Consultar campañas y evidencia</span><span class="check-item">${ico('check')} Registrar seguimiento autorizado</span></div></section></div><p class="footnote">El selector superior permite explorar estos perfiles. No es autenticación ni control de acceso productivo. La evolución requiere autorización en servidor.</p><div class="section-heading"><h2>Actividad de esta demostración</h2><p>Solo en este navegador</p></div><section class="panel panel-pad">${state.audit.slice(0,14).map(a=>`<div class="audit-log"><strong>${esc(a.text)}</strong>${esc(a.time)}</div>`).join('')}</section>`;}
const sources=[
['Inbox de Meta Business Suite','Atender conversaciones con permisos y contexto.','https://www.facebook.com/business/help/27148728838061242','Meta'],['Generación de leads por mensajería','Diseñar invitación y preguntas útiles de calificación.','https://about.fb.com/ltam/wp-content/uploads/sites/14/2023/11/LeadGenerationGuide.pdf','Meta'],['Formación en mensajería','Experiencia de conversación y medición.','https://www.facebookblueprint.com/student/activity/637794-meta-business-messaging-tools','Meta'],['Acceso a páginas','Permisos de plataforma diferentes de los roles internos.','https://www.facebook.com/help/289207354498410/','Meta'],['Rendimiento de Search Console','Consultas, páginas, impresiones, clics y CTR.','https://support.google.com/webmasters/answer/7042828?hl=es','Google'],['Rendimiento de Business Profile','Clics para llamar y acciones de perfil, con sus límites.','https://support.google.com/business/answer/9918094?hl=es','Google'],['Mejorar presencia local','Información completa, horarios, fotos y reseñas.','https://support.google.com/business/answer/7091?hl=es','Google'],['Eventos recomendados GA4','Captación, trabajo, calificación y conversión del lead.','https://developers.google.com/analytics/devguides/collection/ga4/reference/events','Google'],['Adquisición de leads en GA4','Leads y eventos por usuarios de Analytics.','https://support.google.com/analytics/answer/16376749?hl=es','Google'],['Enlaces UTM','Normalización del origen y la campaña.','https://support.google.com/analytics/answer/10917952?hl=es','Google'],['Datos personales y Analytics','Excluir nombres, email, teléfono y conversaciones.','https://support.google.com/analytics/answer/6366371?hl=es','Google'],['Atribución GA4','Modelos, alcance y asignación de crédito.','https://support.google.com/analytics/answer/10596866?hl=es','Google'],['Eventos clave y conversiones','Acciones significativas, no simples visitas.','https://support.google.com/analytics/answer/9356034?hl=es','Google']
];
function guide(){return `${heading('Medir para decidir, no para llenar tarjetas.','Investigación oficial Meta y Google · Consulta: 13 octubre 2026.',button('Explorar contactabilidad','target','data-view="contactability"','primary'),'VECTOR / BASE DE CONOCIMIENTO')}<div class="research-banner"><h3>La plataforma hace visible una diferencia esencial.</h3><p>Un clic a WhatsApp no es una conversación. Un clic para llamar no confirma una llamada. Una persona en Analytics no siempre coincide con un contacto único del CRM. El cierre necesita evidencia comercial.</p></div><div class="compact-grid"><section class="panel panel-pad"><h2>Prácticas que se vuelven trabajo</h2><div class="checklist">${['Oferta y CTA claros en perfil, contenido y landing.','Atención con responsable, horario y siguiente acción.','Preguntas de calificación útiles, sin exigir todo al inicio.','Contenido por problemas reales, prueba, oferta y conversación.','Comparar campañas por calidad y avance, además de volumen.','Reconciliar fuentes sin sumar dos veces la misma venta.'].map(s=>`<div class="check-item">${ico('check')}<span>${s}</span></div>`).join('')}</div></section><section class="panel panel-pad"><h2>Indicadores con definición</h2><div class="checklist">${[['contactability','Contactabilidad'],['response','Primera respuesta humana'],['cpql','Costo por lead calificado'],['roas','ROAS comercial'],['webconversion','Conversión web a lead'],['calls','Clics para llamar']].map(([key,name])=>button(name,'info',`data-metric="${key}"`)).join('')}</div><p class="footnote">Sin benchmarks universales ni promesas de ranking, conversiones o ventas.</p></section></div><div class="section-heading"><h2>Fuentes oficiales utilizadas</h2><p>La interpretación de producto es una propuesta propia.</p></div><div class="guide-grid">${sources.map(([title,description,url,owner])=>`<article class="panel guide-card"><span class="source-label">${owner}</span><h3 style="margin-top:12px">${title}</h3><p>${description}</p><a href="${url}" target="_blank" rel="noopener">Consultar documentación ↗</a></article>`).join('')}</div>`;}
const definitions={
leads:['Contactos nuevos','Personas únicas registradas en la cohorte, no número de mensajes.','Deduplicar por identidad en el CRM; varias necesidades pueden crear oportunidades distintas.','CRM de demo'],contactability:['Contactabilidad','Leads con comunicación bidireccional confirmada / leads válidos a contactar × 100.','Registrar un mensaje enviado no confirma que la persona respondió.','Definición operacional propuesta'],qualified:['Prospectos calificados','Personas que cumplen criterios transparentes de necesidad y ajuste a la oferta.','No es sinónimo de comentario, clic o nueva consulta.','CRM de demo'],revenue:['Ventas ganadas','Suma de importes de oportunidades ganadas de la cohorte.','Representa cierre comercial, no dinero cobrado. Moneda homogénea: MXN.','CRM de demo'],response:['Primera respuesta humana','Mediana y percentil 90 del tiempo hasta respuesta humana.','Separar acuses automáticos y explicitar horario. No esconder la cola lenta con un promedio.','Registro de atención'],sessions:['Sesiones web','Sesiones registradas por GA4; no contactos únicos del CRM.','El universo depende de configuración, permisos y consentimiento; los datos del prototipo son ficticios.','GA4'],intent:['Intención de contacto','Clic al canal de contacto, por ejemplo WhatsApp o teléfono.','Evento propio propuesto: contact_intent. No cuenta como conversación ni lead confirmado.','GA4 / eventos propuestos'],webconversion:['Conversión web a lead','Sesiones con captura válida / sesiones elegibles × 100.','generate_lead debe representar la captura confirmada. Evitar contar formularios fallidos.','GA4'],opportunities:['Oportunidades abiertas','Necesidades comerciales que todavía no están ganadas o perdidas.','Una persona puede tener más de una necesidad; no duplicar su identidad.','CRM'],next:['Próxima acción','Compromiso concreto con responsable y fecha para una oportunidad abierta.','Las fechas previstas son distintas del registro de la acción realizada.','CRM'],pipeline:['Valor del pipeline','Suma de valores estimados de oportunidades abiertas.','No es ingreso contratado ni cobrado, y no se presenta como una previsión garantizada.','CRM'],closing:['Cierre de oportunidades resueltas','Ganadas / (ganadas + perdidas) de la misma cohorte.','Mostrar abiertas aparte. No tratar oportunidades todavía abiertas como pérdidas.','CRM'],spend:['Inversión publicitaria','Gasto registrado de las campañas del periodo y canal.','Reconciliar fuentes e importaciones para evitar duplicaciones.','Campañas'],cpql:['Costo por lead calificado','Inversión atribuible / calificados atribuibles de la misma campaña y cohorte.','Si falta calificación, atribución o denominador, no es calculable.','Campañas + CRM'],roas:['ROAS comercial','Importe de ventas ganadas atribuidas / gasto publicitario.','No equivale a ROI, beneficio ni cobro. La atribución no demuestra causalidad.','Campañas + CRM'],reach:['Alcance','Cuentas alcanzadas según la definición de Meta y el ámbito consultado.','No sumar publicaciones o redes como personas únicas; las audiencias se superponen.','Meta'],impressions:['Impresiones','Exposiciones, incluidas las repetidas.','Conservar ámbito y periodo compatibles.','Meta'],ctr:['CTR de enlace','Clics de enlace / impresiones × 100.','Distinguir clics de enlace de todos los clics. No existe objetivo universal.','Meta'],frequency:['Frecuencia','Impresiones / alcance del mismo ámbito y periodo.','Ayuda a contextualizar exposición; sola no confirma fatiga creativa.','Meta'],searchclicks:['Clics desde búsqueda','Clics a tu sitio desde resultados registrados por Search Console.','No representan necesariamente personas únicas ni ventas.','Search Console'],searchctr:['CTR de búsqueda','Clics / impresiones de búsqueda × 100.','Comparar consultas, página, dispositivo y periodo compatibles.','Search Console'],calls:['Clics para llamar','Veces que se hizo clic en el botón de llamada del perfil.','Business Profile no demuestra aquí una llamada conectada, atendida o vendida.','Google Business Profile'],attribution:['Origen y atribución','Origen declarado, vínculo CRM y crédito de plataforma son lecturas distintas.','Conservar modelo/ventana; las mismas ventas no se suman por cada plataforma.','CRM / plataformas'],connections:['Conexiones reales','Cuentas externas con autorización y lectura verificadas.','En esta demo hay cero. La configuración local no activa una API.','Estado real del prototipo']
};
function metricDetail(key){const d=definitions[key]||definitions.leads;openDialog(d[0],`<div class="metric-definition"><small>DEFINICIÓN</small><strong>${esc(d[1])}</strong></div><div class="metric-definition"><small>LÍMITE E INTERPRETACIÓN</small><p>${esc(d[2])}</p></div><p>Fuente prevista: ${esc(d[3])}. Datos ficticios en este prototipo.</p>${button('Consultar guía y fuentes','book','data-dialog-view="guide"','primary')}`,'VECTOR / MÉTRICA EXPLICADA');}

function createTask(title){if(state.tasks.some(t=>t.title===title&&!t.done)){toast('Esa tarea ya está pendiente.');return;}state.tasks.push({id:`task-${Date.now()}`,title,owner:state.role==='admin'?'Karloz':'Usuario de marca',type:'mejora',done:false});log(`Tarea creada: ${title}`);renderNav();toast('Tarea creada. La encontrarás en el Centro de mando.');}
function utmBuilder(id){const c=state.campaigns.find(x=>x.id===id);openDialog('Un enlace, un origen claro',`<p>Normaliza la fuente, el medio y la campaña. No incluyas nombres, teléfonos, email ni texto de conversaciones.</p><form id="utm-form"><div class="form-grid"><div class="field wide"><label for="utm-url">Página de destino</label><input type="url" required id="utm-url" name="url" value="https://www.vectorinside.com/"></div><div class="field"><label for="utm-source">Fuente</label><input required pattern="[a-z0-9_-]+" maxlength="60" id="utm-source" name="source" value="${c?.channel==='google'?'google':'instagram'}"></div><div class="field"><label for="utm-medium">Medio</label><select id="utm-medium" name="medium"><option value="organic_social">organic_social</option><option value="paid_social">paid_social</option><option value="cpc">cpc</option><option value="organic">organic</option><option value="email">email</option></select></div><div class="field"><label for="utm-campaign">Campaña</label><input required pattern="[a-z0-9_-]+" maxlength="60" id="utm-campaign" name="campaign" value="${c?.id||'vi_contacto_202610'}"></div><div class="field"><label for="utm-content">Pieza / variante</label><input pattern="[a-z0-9_-]*" maxlength="60" id="utm-content" name="content" value="reel_proceso_a"></div></div><div class="form-actions">${button('Construir enlace','link','type="submit"','primary')}</div></form><div id="utm-output"></div>`,'VECTOR / TRAZABILIDAD');document.getElementById('utm-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);const u=new URL(fd.get('url'));if(!['https:','http:'].includes(u.protocol)){toast('El enlace debe usar HTTP o HTTPS.');return;}u.searchParams.set('utm_source',fd.get('source'));u.searchParams.set('utm_medium',fd.get('medium'));u.searchParams.set('utm_campaign',fd.get('campaign'));if(fd.get('content'))u.searchParams.set('utm_content',fd.get('content'));document.getElementById('utm-output').innerHTML=`<div class="builder-output">${esc(u.href)}</div><p class="footnote">El enlace está preparado; no se visitó ni publicó.</p>${button('Copiar enlace','copy','data-copy-utm','link')}`;document.querySelector('[data-copy-utm]').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(u.href);toast('Enlace copiado.');}catch{toast('Selecciona el enlace para copiarlo manualmente.');}});});}
function searchDialog(){openDialog('Encuentra el contexto',`<label class="field"><span>Contacto, empresa, necesidad o campaña</span><input id="global-search" placeholder="Escribe para buscar…" autocomplete="off"></label><div class="search-results" id="global-results"></div>`,'VECTOR / BÚSQUEDA');const input=document.getElementById('global-search');const update=()=>{const q=input.value.trim().toLowerCase();const leads=state.leads.filter(l=>`${l.name} ${l.company} ${l.need}`.toLowerCase().includes(q)).slice(0,5),camps=state.campaigns.filter(c=>c.name.toLowerCase().includes(q)).slice(0,3);document.getElementById('global-results').innerHTML=q?leads.map(l=>`<button class="search-result" data-lead="${l.id}"><span>${esc(l.name)}<small> · ${esc(l.company)}</small></span>${badge(l.stage)}</button>`).join('')+camps.map(c=>`<button class="search-result" data-campaign="${c.id}"><span>${esc(c.name)}</span><small>Campaña</small></button>`).join('')||'<p class="footnote">No hay coincidencias en la demo.</p>':'<p class="footnote">La búsqueda mantiene el contexto del mismo espacio de trabajo.</p>';};input.addEventListener('input',update);update();input.focus();}
function csvCell(value){let str=String(value??'');if(/^[\s]*[=+@-]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"';}
function exportCSV(type){let rows;if(type==='leads')rows=[['Nombre ficticio','Empresa','Necesidad','Etapa','Origen','Responsable','Próxima acción','Valor MXN'],...filteredLeads().map(l=>[l.name,l.company,l.need,l.stage,sourceName(l.source),l.owner,l.next,l.value])];else{const reportChannel=state.view==='results'&&state.resultsTab==='meta'?'meta':state.view==='results'&&state.resultsTab==='google'?'google':state.channel;const m=aggregate(reportChannel);rows=[['REPORTE DEMO','VECTOR COMUNITY','Datos ficticios'],['Periodo',state.period==='7'?'7–13 octubre 2026':'14 septiembre–13 octubre 2026'],['Canal',sourceName(reportChannel)],['Métrica','Valor','Definición'],['Captaciones válidas',m.leads.length,'Personas únicas de la cohorte'],['Contactabilidad',pct(m.contacted.length,m.leads.length),'Intercambio confirmado / leads válidos'],['Calificados',m.qualified.length,'Criterios evaluados'],['Inversión MXN',m.spend,'Campañas demo'],['Ventas ganadas MXN',m.revenue,'Importe comercial, no cobros'],['Venta atribuida MXN',m.attributed,'Crédito CRM fixture'],['ROAS comercial',m.spend?m.attributed/m.spend:'No calculable','Venta atribuida / inversión'],['ROI','No calculable','Faltan costos y margen']];}const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`vector-${type}-demo.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Reporte de demostración descargado.');}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(field);field='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field='';}else field+=ch;}if(quoted)throw new Error('Hay comillas sin cerrar.');row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function importDialog(){if(state.role!=='admin')return;openDialog('Importar contactos de ejemplo',`<p>CSV de hasta 500 KB y 200 filas. Cabeceras: nombre, empresa, necesidad, origen. La demo identifica repetidos por nombre + empresa; producción requiere identificadores fiables.</p><div class="field"><label for="csv-file">Archivo CSV con datos ficticios</label><input id="csv-file" type="file" accept=".csv,text/csv"></div><div class="builder-output">nombre,empresa,necesidad,origen<br>Contacto Ejemplo,Empresa Ejemplo,Página web,meta</div><div id="csv-preview"></div>`,'VECTOR / IMPORTACIÓN LOCAL');document.getElementById('csv-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>500000){toast('El límite de esta demo es 500 KB.');return;}let rows;try{rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));}catch(error){toast(error.message);return;}const headers=rows.shift()?.map(x=>x.trim().toLowerCase())||[];if(!['nombre','empresa','necesidad','origen'].every(h=>headers.includes(h))){toast('Faltan cabeceras: nombre, empresa, necesidad, origen.');return;}if(rows.length>200){toast('La demo admite hasta 200 filas.');return;}const seen=new Set(state.leads.map(l=>`${l.name.toLowerCase()}|${l.company.toLowerCase()}`));const preview=rows.map((row,i)=>{const get=key=>(row[headers.indexOf(key)]||'').trim();const item={name:get('nombre'),company:get('empresa'),need:get('necesidad'),source:get('origen').toLowerCase()};const key=`${item.name.toLowerCase()}|${item.company.toLowerCase()}`;const error=!item.name||!item.company||!item.need?'Campos obligatorios incompletos':!['meta','google','direct'].includes(item.source)?'Origen debe ser meta, google o direct':seen.has(key)?'Repetido en demo/archivo':'';if(!error)seen.add(key);return{...item,row:i+2,error};});const valid=preview.filter(x=>!x.error);document.getElementById('csv-preview').innerHTML=`<div class="separator"></div><h3>${valid.length} válidas · ${preview.length-valid.length} rechazadas</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Fila</th><th>Nombre</th><th>Resultado</th></tr></thead><tbody>${preview.slice(0,30).map(x=>`<tr><td>${x.row}</td><td>${esc(x.name)}</td><td>${esc(x.error||'Válida')}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Vista previa de hasta 30 filas. La importación aplica todas las filas válidas.</p>${button('Confirmar filas válidas','check','id="confirm-import"','primary')}`;document.getElementById('confirm-import').disabled=!valid.length;document.getElementById('confirm-import').addEventListener('click',()=>{valid.forEach((item,i)=>state.leads.push({...item,id:`lead-import-${Date.now()}-${i}`,campaign:'',stage:'Nuevo',owner:'Karloz',next:'Revisar captación importada',nextDate:'2026-10-14',value:0,date:DEMO_DATE,contacted:false,responseMinutes:null,qualified:false,closedAt:'',lostReason:'',attributedValue:0,history:[{date:DEMO_DATE,text:'Importación CSV de demo · Origen declarado'}]}));log(`CSV demo importado: ${valid.length} filas válidas.`);closeDialog();render();toast(`${valid.length} contactos de ejemplo importados.`);});});}

document.addEventListener('click',event=>{
  const target=event.target.closest('button,a');if(!target)return;const d=target.dataset;
  if(d.view){event.preventDefault();navigate(d.view);}
  else if(d.dialogView){closeDialog();navigate(d.dialogView);}
  else if(d.metric)metricDetail(d.metric);
  else if(d.campaign)campaignDetail(d.campaign);
  else if('newCampaign'in d)campaignForm();
  else if('proposeCampaign'in d)campaignForm(true);
  else if(d.campaignLeads){closeDialog();leadFilter='all';navigate('crm');leadCampaign=d.campaignLeads;render();}
  else if('clearCampaign'in d){leadCampaign='all';render();}
  else if('utm'in d)utmBuilder(d.utm);
  else if('newPost'in d)postForm();
  else if(d.post)postDetail(d.post);
  else if(d.editPost)postForm(d.editPost);
  else if(d.approvePost){const p=state.posts.find(p=>p.id===d.approvePost);if(p?.status==='Revisión'){p.status='Aprobado';p.approval={by:state.role==='admin'?'Administrador':'Usuario de marca',date:DEMO_DATE,version:p.version};log(`Versión ${p.version} aprobada: ${p.title}`);postDetail(p.id);render();toast('Versión aprobada. No se publicó ni programó.');}}
  else if(d.changesPost)changesPost(d.changesPost);
  else if(d.reviewPost){if(state.role!=='admin')return;const p=state.posts.find(p=>p.id===d.reviewPost);p.status='Revisión';log(`Revisión solicitada para ${p.title}, v${p.version}.`);postDetail(p.id);render();}
  else if(d.publishPost)publishPost(d.publishPost);
  else if(d.contentMode){state.contentMode=d.contentMode;save();render();}
  else if('ideas'in d)ideas();
  else if(d.idea){postForm();document.getElementById('post-hook').value=d.idea;document.getElementById('post-title').value='Idea: '+d.idea.slice(0,65);}
  else if(d.lead)leadDetail(d.lead);
  else if('newLead'in d)leadForm();
  else if(d.thread){state.selectedThread=d.thread;save();render();}
  else if(d.draftReply){const l=state.leads.find(l=>l.id===d.draftReply);document.getElementById('reply-message').value=`Hola ${l.name.split(' ')[0]}, gracias por escribir a Vector Inside. Para orientarte con ${l.need.toLowerCase()}, ¿qué necesitas mejorar primero y qué resultado esperas? Podemos revisar contigo el siguiente paso.`;toast('Borrador editable preparado con una plantilla local.');}
  else if(d.confirmContact){const l=state.leads.find(l=>l.id===d.confirmContact);l.contacted=true;l.responseMinutes=l.responseMinutes??null;l.history.push({date:DEMO_DATE,text:'Intercambio bidireccional confirmado por el operador · Demo'});log(`Contacto confirmado: ${l.name}`);leadDetail(l.id);render();}
  else if(d.crmMode){state.crmMode=d.crmMode;save();render();}
  else if(d.resultsTab){state.resultsTab=d.resultsTab;save();render();}
  else if(d.createTask)createTask(d.createTask);
  else if(d.completeTask){const t=state.tasks.find(t=>t.id===d.completeTask);if(t){t.done=true;log(`Tarea completada: ${t.title}`);render();toast('Tarea completada en esta demo.');}}
  else if(d.export)exportCSV(d.export);
  else if('newExperiment'in d)newExperiment();
  else if(d.experiment){const ex=state.experiments.find(x=>x.id===d.experiment);openDialog('Registrar aprendizaje',`<p>${esc(ex.name)}. Documenta lo observado y los límites antes de decidir.</p><form id="learning-form"><div class="field"><label for="learning">Aprendizaje / siguiente prueba</label><textarea id="learning" name="learning" required maxlength="1000">${esc(ex.learning||'')}</textarea></div><div class="form-actions">${button('Guardar aprendizaje','check','type="submit"','primary')}</div></form>`);document.getElementById('learning-form').addEventListener('submit',e=>{e.preventDefault();ex.learning=new FormData(e.target).get('learning').trim();log(`Aprendizaje registrado: ${ex.name}`);closeDialog();render();toast('Aprendizaje guardado; no se declaró un ganador.');});}
  else if('openWebsite'in d)window.open(state.profile.website,'_blank','noopener');
  else if('connection'in d){const c=connectionData[Number(d.connection)];openDialog(c[0],`<p>${esc(c[2])}</p><div class="metric-definition"><small>ANTES DE INTEGRAR</small><strong>${esc(c[3])}</strong></div><div class="metric-note">Sin conexión real. Esta pantalla explica el plan; no inicia autorización ni pide credenciales.</div>${button('Crear tarea de integración','plus',`data-create-task="Validar permisos e integración de ${esc(c[0])}"`,'primary')}`,'VECTOR / PLAN DE CONEXIÓN');}
  else if('import'in d)importDialog();
  else if('reset'in d)openDialog('Restablecer la demostración',`<p>Se borrarán únicamente los cambios locales de este prototipo y se recuperarán sus datos ficticios iniciales. Los archivos del repositorio y las cuentas externas no se modifican.</p><div class="form-actions">${button('Cancelar','close','data-close-dialog')}${button('Restablecer demo','settings','data-confirm-reset','danger')}</div>`);
  else if('confirmReset'in d){state=seed();searchQuery='';leadFilter=leadCampaign=campaignFilter=contentFilter='all';save();closeDialog();render();toast('Datos ficticios iniciales restaurados.');}
  else if('closeDialog'in d)closeDialog();
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='period-filter'){state.period=el.value;save();render();}else if(el.id==='channel-filter'){state.channel=el.value;save();render();}else if(el.id==='meta-read'){state.metaRead=el.value;save();render();}else if(el.id==='campaign-filter'){campaignFilter=el.value;render();}else if(el.id==='content-filter'){contentFilter=el.value;render();}else if(el.id==='lead-filter'){leadFilter=el.value;render();}else if('googleCheck'in el.dataset){state.googleChecks[Number(el.dataset.googleCheck)]=el.checked;save();}});
document.addEventListener('input',event=>{if(['campaign-search','lead-search'].includes(event.target.id)){const id=event.target.id,start=event.target.selectionStart;searchQuery=event.target.value;render();const input=document.getElementById(id);input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('submit',event=>{
  if(event.target.id==='reply-form'){event.preventDefault();const text=document.getElementById('reply-message').value.trim();if(!text)return;const l=state.leads.find(l=>l.id===state.selectedThread);state.messages[l.id]=state.messages[l.id]||[{direction:'in',text:`Consulta sobre ${l.need}`,time:'Entrada de demostración'}];state.messages[l.id].push({direction:'out',text,time:'Respuesta registrada solo en la demo'});if(l.owner==='Sin asignar')l.owner=state.role==='admin'?'Alexandra':'Usuario de marca';l.history.push({date:DEMO_DATE,text:'Respuesta de prueba registrada; entrega externa no realizada.'});log(`Respuesta local registrada para ${l.name}; sin envío externo.`);render();toast('Respuesta registrada localmente. Contacto bidireccional aún requiere confirmación.');}
  else if(event.target.id==='profile-form'){event.preventDefault();if(state.role!=='admin')return;const fd=new FormData(event.target);const u=new URL(fd.get('website'));if(!['https:','http:'].includes(u.protocol)){toast('El sitio debe usar HTTP o HTTPS.');return;}for(const key of ['name','offer','audience','tone','cta','goal','hours'])state.profile[key]=fd.get(key).trim();state.profile.website=u.href;state.profile.sla=Number(fd.get('sla'));log('Perfil de marca y objetivo de atención actualizados.');render();toast('Perfil de demostración guardado.');}
});
document.getElementById('role-select').addEventListener('change',e=>{state.role=e.target.value;log(`Perfil de exploración cambiado a ${state.role==='admin'?'Administrador':'Usuario'}.`);render();toast('Perfil de exploración actualizado. No es un inicio de sesión real.');});
document.getElementById('theme-button').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();renderNav();});
document.getElementById('search-trigger').addEventListener('click',searchDialog);
document.getElementById('sidebar-close').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('menu-button').setAttribute('aria-expanded','false');syncSidebar();document.getElementById('menu-button').focus();});
document.getElementById('notifications-button').addEventListener('click',()=>navigate('overview'));
document.getElementById('dialog-close').addEventListener('click',closeDialog);
dialog.addEventListener('click',e=>{if(e.target===dialog){const box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)closeDialog();}});
document.getElementById('menu-button').addEventListener('click',()=>{const sidebar=document.getElementById('sidebar');const opened=sidebar.classList.toggle('open');document.getElementById('menu-button').setAttribute('aria-expanded',String(opened));syncSidebar();});
document.getElementById('demo-info').addEventListener('click',()=>openDialog('Explora el recorrido completo',`<p>Este prototipo local demuestra la evolución propuesta de VECTOR COMUNITY. Usa los perfiles Administrador y Usuario para explorar sus responsabilidades.</p><div class="checklist"><div class="check-item">${ico('message')} Atiende una consulta y registra el siguiente paso.</div><div class="check-item">${ico('content')} Revisa, aprueba y edita una versión de contenido.</div><div class="check-item">${ico('chart')} Consulta una métrica y abre su evidencia.</div><div class="check-item">${ico('lab')} Convierte una hipótesis en una tarea.</div></div><p>Los cambios se guardan en este navegador. No hay autenticación productiva ni APIs de Meta/Google conectadas, y ninguna acción publica o envía mensajes. Evita datos personales reales.</p>${button('Comenzar por una conversación','arrow','data-dialog-view="inbox"','primary')}`,'VECTOR / PROTOTIPO LOCAL'));
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();}if(e.key==='Escape'){document.getElementById('sidebar').classList.remove('open');syncSidebar();document.getElementById('menu-button').setAttribute('aria-expanded','false');}});
render();

window.addEventListener('resize',()=>{syncSidebar();const svg=document.querySelector('.chart-svg');if(svg)svg.outerHTML=chart();});
